import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';

/**
 * A pool's member: a person (personId) or another pool (poolId), its name, its share percent (two decimals), whether
 * it is a person with a retirement date set and its cut of the pool's pot ('': none — the pool is unbalanced, or has
 * no pot). A pool that is a member of none has the sheet's pot; one that is a member of another, its cut there.
 */
export type PoolMember = {
  personId: number | null;
  poolId: number | null;
  name: string;
  share: string;
  retired: boolean;
  cut: string;
};

/**
 * A pool on the sheet: its members in the order they were added, the total share (a retired member's share counts
 * as 0.00) and whether that total is exactly 100.00.
 */
export type Pool = { id: number; name: string; members: PoolMember[]; totalShare: string; balanced: boolean };

/** The query key for the sheet's pools; under sheetKey, so re-loading the sheet re-reads them. */
export const poolsKey = (sheet: string) => [...sheetKey(sheet), 'pools'] as const;

/** The sheet's pools, in the order they were added. */
export function usePools() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: poolsKey(sheet),
    queryFn: () => getJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheet)}/pools`),
    enabled: !!sheet,
  });
}
import { HomeMain } from '../../slots/defs/homeMain';
import { Pools } from './Pools';

export const contribution = HomeMain.fill({ order: 9.9, Component: Pools });
import { ClaimRowValues } from '../../slots/defs/claimRow';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { ClaimDue } from './ClaimDue';
import { PersonDueTotal } from './PersonDueTotal';
import { PersonExcess } from './PersonExcess';

export const contributions = [
  PersonColumnHeads.fill({ order: 15, Component: () => <th>Due</th> }),
  PersonColumns.fill({ order: 15, Component: PersonDueTotal }),
  PersonColumnHeads.fill({ order: 15.5, Component: () => <th>Excess</th> }),
  PersonColumns.fill({ order: 15.5, Component: PersonExcess }),
  ClaimRowValues.fill({ order: 10, Component: ClaimDue }),
];
import { useClaims } from '../claims/claims';
import { liveHolds, usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useDueRules } from '../settings/settings';
import { personDue, trimmedTotal, useRates } from './rates';

// The sheet's due-total: everyone's due-total added up, skipping those that are n/a, trimmed of the highest and lowest.
export function DueTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();

  if (!user || !sheet) return null;

  const dues = people.map((p) => personDue(claims.filter((c) => c.personId === p.id), rates, p.grades, liveHolds(p, rules.today), rules));
  return (
    <p>
      Due total: <strong data-testid="rollup-due-total">{trimmedTotal(dues)}</strong>
    </p>
  );
}
import { useClaims } from '../claims/claims';
import { liveHolds } from '../people/people';
import type { Person } from '../people/people';
import { useDueRules } from '../settings/settings';
import { personExcess, useRates } from './rates';

// A person's excess: by how much the figures of their claims that count are above the sheet's cap; 0.00 otherwise.
export function PersonExcess({ person }: { person: Person }) {
  const rates = useRates().data ?? [];
